const app = require('./app');
const { sequelize } = require('./models');
const ingestJob = require('./jobs/ingestJob');

const PORT = process.env.PORT || 4000;

async function start() {
  try {
    await sequelize.sync(); // creates tables in SQLite or Postgres
    app.listen(PORT, () => {
      console.log(`Server listening on ${PORT}`);
    });

    // Start scheduled ingestion (every 6 hours)
    ingestJob.start();
  } catch (err) {
    console.error('Failed to start server', err);
    process.exit(1);
  }
}

