const { Program } = require('../models');
const { Op } = require('sequelize');

exports.searchPrograms = async (req, res) => {
  const { q, tag, platform, minReward, maxReward, limit = 20, offset = 0 } = req.query;
  const where = {};

  if (q) {
    where[Op.or] = [
      { name: { [Op.like]: `%${q}%` } },
      { tags: { [Op.like]: `%${q}%` } },
      { scope: { [Op.like]: `%${q}%` } }
    ];
  }

  if (tag) where.tags = { [Op.like]: `%${tag}%` };
  if (platform) where.platforms = { [Op.like]: `%${platform}%` };
  if (minReward) where.rewardMax = { [Op.gte]: Number(minReward) };
  if (maxReward) where.rewardMin = { [Op.lte]: Number(maxReward) };

  const programs = await Program.findAll({ where, limit: Number(limit), offset: Number(offset) });
  res.json(programs);
};

exports.getProgram = async (req, res) => {
  const p = await Program.findByPk(req.params.id);
  if (!p) return res.status(404).json({ error: 'Not found' });
  res.json(p);
};

