module.exports = function normalize(data) {
  // Basic normalization: ensure arrays for tags/platforms, numbers for reward
  return {
    externalId: data.externalId || null,
    name: data.name || data.title,
    url: data.url,
    rewardMin: data.rewardMin ? Number(data.rewardMin) : null,
    rewardMax: data.rewardMax ? Number(data.rewardMax) : null,
    currency: data.currency || 'USD',
    tags: Array.isArray(data.tags) ? data.tags : (data.tags ? String(data.tags).split(',').map(t => t.trim()) : []),
    platforms: Array.isArray(data.platforms) ? data.platforms : (data.platforms ? String(data.platforms).split(',').map(p => p.trim()) : []),
    scope: data.scope || '',
    status: data.status || 'active',
    source: data.source || 'unknown'
  };
};

