18) frontend/src/App.jsx (simple UI)
import React, { useEffect, useState } from 'react';
import api from './api/api';

function App() {
  const [programs, setPrograms] = useState([]);
  const [q, setQ] = useState('');

  useEffect(() => {
    fetchPrograms();
  }, []);

  const fetchPrograms = async (query) => {
    const resp = await api.get('/programs', { params: { q: query } });
    setPrograms(resp.data);
  };

  const handleSearch = async (e) => {
    e.preventDefault();
    await fetchPrograms(q);
  };

  return (
    <div style={{ padding: 20 }}>
      <h1>Bug Bounty Programs</h1>
      <form onSubmit={handleSearch}>
        <input value={q} onChange={(e) => setQ(e.target.value)} placeholder="Search by name, tag, scope..." />
        <button type="submit">Search</button>
      </form>
      <div style={{ marginTop: 20 }}>
        {programs.map(p => (
          <div key={p.id} style={{ border: '1px solid #ddd', padding: 10, marginBottom: 10 }}>
            <a href={p.url} target="_blank" rel="noreferrer"><strong>{p.name}</strong></a>
            <div>Reward: {p.rewardMin || 'N/A'} - {p.rewardMax || 'N/A'} {p.currency || ''}</div>
            <div>Tags: {p.tags}</div>
            <div>Platforms: {p.platforms}</div>
          </div>
        ))}
      </div>
    </div>
  );
}

export default App;

