// Runs multiple ingestion sources and upserts results into DB
const hackeroneService = require('./hackeroneService');
const bugcrowdService = require('./bugcrowdService');
const scraperService = require('./scraperService');
const { Program } = require('../models');

async function upsertProgram(data) {
  // normalize incoming data
  const normalized = require('../utils/normalize')(data);

  const [program, created] = await Program.upsert({
    externalId: normalized.externalId || null,
    name: normalized.name,
    url: normalized.url,
    rewardMin: normalized.rewardMin,
    rewardMax: normalized.rewardMax,
    currency: normalized.currency,
    tags: (normalized.tags || []).join(','),
    platforms: (normalized.platforms || []).join(','),
    scope: normalized.scope,
    status: normalized.status || 'active',
    source: normalized.source || null,
    lastSeenAt: new Date()
  }, { returning: true });

  return program;
}

async function runAll() {
  const results = [];

  // Example: call services in sequence
  const sample = await scraperService.getSamplePrograms();
  for (const p of sample) {
    const res = await upsertProgram(p);
    results.push({ id: res.id, name: res.name });
  }

  // In the future: call hackeroneService.fetchPrograms() if API keys are configured
  return { ingested: results.length, items: results.slice(0, 20) };
}

module.exports = { runAll, upsertProgram };

