  return {
    externalId: data.externalId || null,
    name: data.name || data.title,
    url: data.url,
    rewardMin: data.rewardMin ? Number(data.rewardMin) : null,
    rewardMax: data.rewardMax ? Number(data.rewardMax) : null,
    currency: data.currency || 'USD',
