    platforms: Array.isArray(data.platforms) ? data.platforms : (data.platforms ? String(data.platforms).split(',').map(p => p.trim()) : []),
    scope: data.scope || '',
    status: data.status || 'active',
    source: data.source || 'unknown'
  };
};

